    Exercise(seed.id, seed.name, seed.category, seed.primaryMuscles, seed.secondaryMuscles, seed.instructions, seed.safetyNote, seed.defaultSets, seed.defaultReps, seed.defaultWeightKg, seed.defaultDurationMinutes, seed.defaultDistanceKm)
